{%- comment -%} sections/featured-benefits.liquid {%- endcomment -%}
<section class="benefits" aria-labelledby="benefits-title">
  {%- if section.settings.title != blank -%}<h2 id="benefits-title" class="benefits__title">{{ section.settings.title | escape }}</h2>{%- endif -%}
  <ul class="benefits__grid" role="list">
    {%- for block in section.blocks -%}
      <li class="benefits__item" {{ block.shopify_attributes }}>
        {%- if block.settings.icon != blank -%}<img class="benefits__icon" src="{{ block.settings.icon | image_url: width: 96 }}" alt="" width="48" height="48" loading="lazy">{%- endif -%}
        <h3 class="benefits__heading">{{ block.settings.heading | escape }}</h3>
        <div class="benefits__text rte">{{ block.settings.text }}</div>
      </li>
    {%- endfor -%}
  </ul>
</section>
{%- style -%}
  .benefits{padding:var(--section-pad,3rem) 0}
  .benefits__grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1.5rem;list-style:none;margin:0;padding:0}
  .benefits__icon{margin-bottom:.75rem}
{%- endstyle -%}
{% schema %}
{
  "name": "Featured benefits",
  "tag": "section",
  "settings": [{ "type": "text", "id": "title", "label": "Heading", "default": "Why it works" }],
  "blocks": [{ "type": "benefit", "name": "Benefit", "settings": [
    { "type": "image_picker", "id": "icon", "label": "Icon" },
    { "type": "text", "id": "heading", "label": "Heading", "default": "Benefit" },
    { "type": "richtext", "id": "text", "label": "Text" }
  ]}],
  "max_blocks": 6,
  "presets": [{ "name": "Featured benefits", "blocks": [{ "type": "benefit" }, { "type": "benefit" }, { "type": "benefit" }] }]
}
{% endschema %}
